const TokenInfo* parser_token_info(TokenType type) {
  static const TokenInfo unknown = {.name = "unknown token"};
  if ((size_t)type >= sizeof(token_infos) / sizeof(*token_infos) ||
      token_infos[type].name == NULL)
    return &unknown;
  return &token_infos[type];
}

// === NONTERMINAL FUNCTIONS ===
//
// One function per nonterminal of the LL table (IFJ26 Table Maker project),
// except the expression nonterminals, which the precedence parser stands in
// for (guidance/parser-structure/adr/0003). Rule numbers are the table's.
// Template:
//
//   // <NONTERMINAL> -> ...   (LL table rules N, M)
//   static void parse_<nonterminal>(Ctx* ctx, Parser* parser, AstNode* parent)
//   {
//     switch (parser_current(parser)->type) {
//       // Rule N: <NONTERMINAL> -> <terminal A> <OTHER_NONTERMINAL>
//       case <terminal in the predict set of rule N>: {
//         // Create the node and attach it to parent right away, before
//         // parsing its children, so ctx_free frees it after a THROW
//         AstNode* node = attach_node(ctx, parser, parent, AST_NODE_...);
//
//         // Copy token text before consuming the token (it is freed)
//         ast_node_set_name(ctx, node, parser_current(parser)->value.text);
//         parser_expect(ctx, parser, <terminal A>);
//         parse_<other_nonterminal>(ctx, parser, node);
//         return;
//       }
//
//       // Rule M: <NONTERMINAL> -> ε, predict set is FOLLOW(<NONTERMINAL>)
//       case <terminal in the follow set>:
//         return;
//
//       default:
//         parser_syntax_error(ctx, parser, "<terminals of all predict sets>");
//     }
//   }
//
// Expressions are handed to the precedence parser: expr_parse (expr_parser.h)
// returns the expression's subtree, to be attached to the parent node.

// Changes: new, the append that cannot leak the node when it throws.
void parser_attach(Ctx* ctx, Parser* parser, AstNode* parent, AstNode* child) {
  parser->pending = child;
  ast_node_append_child(ctx, parent, child);
  parser->pending = NULL;
}

// Changes: appends with parser_attach, so the node is not leaked when the
// append runs out of memory.
/**
 * @brief Creates a node of given kind at the current token's position and
 * attaches it to parent
 */
static AstNode* attach_node(Ctx* ctx,
                            Parser* parser,
                            AstNode* parent,
                            AstNodeType type) {
  AstNode* node;
  ast_node_create(ctx, &node);
  ast_node_set_type(node, type);
  ast_node_set_position(node, parser_current(parser)->line,
                        parser_current(parser)->column);
  parser_attach(ctx, parser, parent, node);
  return node;
}

/**
 * @brief Attaches an IDENT node for the current token and consumes it
 */
static void attach_ident(Ctx* ctx, Parser* parser, AstNode* parent) {
  if (parser_current(parser)->type != IDENT)
    parser_syntax_error(ctx, parser, "identifier");
  AstNode* ident = attach_node(ctx, parser, parent, AST_NODE_IDENT);
  ast_node_set_name(ctx, ident, parser_current(parser)->value.text);
  parser_advance(ctx, parser);
}

// Changes: appends with parser_attach, so the expression is not leaked when the
// append runs out of memory.
/**
 * @brief Parses an expression with the precedence parser and attaches it
 */
static void attach_expr(Ctx* ctx, Parser* parser, AstNode* parent) {
  AstNode* expr = expr_parse(ctx, parser);
  parser_attach(ctx, parser, parent, expr);
}

// Expected terminals of the predict sets shared by several functions
#define EXPECTED_TYPE "Int, Double, String, Unit, Boolean or List"

// Changes: a TYPE_LIST type builds a TYPE_LIST [elem] node.
// TYPE -> TYPE_INT | TYPE_DOUBLE | TYPE_STRING | TYPE_UNIT | TYPE_BOOL
// | TYPE_LIST L_BRACKET TYPE R_BRACKET (rules 9 to 14)
// NOLINTNEXTLINE(misc-no-recursion)
static void parse_type(Ctx* ctx, Parser* parser, AstNode* parent) {
  AstDataType data_type;
  switch (parser_current(parser)->type) {
    case TYPE_LIST: {
      AstNode* list = attach_node(ctx, parser, parent, AST_NODE_TYPE_LIST);
      parser_advance(ctx, parser);
      parser_expect(ctx, parser, L_BRACKET);
      parse_type(ctx, parser, list);
      parser_expect(ctx, parser, R_BRACKET);
      return;
    }
    case TYPE_INT:
      data_type = AST_DATA_TYPE_INT;
      break;
    case TYPE_DOUBLE:
      data_type = AST_DATA_TYPE_DOUBLE;
      break;
    case TYPE_STRING:
      data_type = AST_DATA_TYPE_STRING;
      break;
    case TYPE_UNIT:
      data_type = AST_DATA_TYPE_UNIT;
      break;
    case TYPE_BOOL:
      data_type = AST_DATA_TYPE_BOOLEAN;
      break;
    default:
      parser_syntax_error(ctx, parser, EXPECTED_TYPE);
      return;  // unreachable
  }

  AstNode* type = attach_node(ctx, parser, parent, AST_NODE_TYPE_ANNOTATION);
  ast_node_set_data_type(type, data_type);
  parser_advance(ctx, parser);
}

// PARAM -> IDENT COLON TYPE (rule 24)
static void parse_param(Ctx* ctx, Parser* parser, AstNode* parent) {
  if (parser_current(parser)->type != IDENT)
    parser_syntax_error(ctx, parser, "identifier");

  AstNode* param = attach_node(ctx, parser, parent, AST_NODE_PARAM);
  attach_ident(ctx, parser, param);
  parser_expect(ctx, parser, COLON);
  parse_type(ctx, parser, param);
}

static void parse_param_tail(Ctx* ctx, Parser* parser, AstNode* parent);

// PARAM_NEXT -> PARAM PARAM_TAIL | ε (rules 22, 23)
static void parse_param_next(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IDENT:
      parse_param(ctx, parser, parent);
      parse_param_tail(ctx, parser, parent);
      return;
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, "identifier or )");
  }
}

// Changes: new, consumes the COMMA of a PARAM_TAIL or ARG_TAIL. A trailing
// comma is allowed only with a line break (the hidden EOL, ADR-0007) before the
// `)` (PDF 1.2).
static void parse_list_comma(Ctx* ctx, Parser* parser) {
  parser_advance(ctx, parser);
  if (parser_current(parser)->type == R_PAREN &&
      !parser_after_line_break(parser))
    parser_syntax_error(ctx, parser,
                        "a line break between the trailing , and )");
}

// Changes: the COMMA goes through parse_list_comma.
// PARAM_TAIL -> COMMA PARAM_NEXT | ε (rules 20, 21)
static void parse_param_tail(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case COMMA:
      parse_list_comma(ctx, parser);
      parse_param_next(ctx, parser, parent);
      return;
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, ", or )");
  }
}

// PARAM_LIST -> PARAM PARAM_TAIL | ε (rules 18, 19)
static void parse_param_list(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IDENT:
      parse_param(ctx, parser, parent);
      parse_param_tail(ctx, parser, parent);
      return;
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, "identifier or )");
  }
}

// Changes: rule 16 is FUNC_PARAMS -> UNIT, the type name TYPE_UNIT is no
// parameter list (ADR-0009).
// FUNC_PARAMS -> UNIT | L_PAREN PARAM_LIST R_PAREN (rules 16, 17)
// Attaches the PARAM_LIST, empty for `def f()`.
static void parse_func_params(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    // `()` is one token, the unit value (GLOSSARY.md, Unit value)
    case UNIT:
      attach_node(ctx, parser, parent, AST_NODE_PARAM_LIST);
      parser_advance(ctx, parser);
      return;
    case L_PAREN: {
      AstNode* list = attach_node(ctx, parser, parent, AST_NODE_PARAM_LIST);
      parser_advance(ctx, parser);
      parse_param_list(ctx, parser, list);
      parser_expect(ctx, parser, R_PAREN);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "( or ()");
  }
}

// FUNC_TYPE -> COLON TYPE | ε (rules 25, 26)
// Attaches the return type, NONE when omitted.
static void parse_func_type(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case COLON:
      parser_advance(ctx, parser);
      parse_type(ctx, parser, parent);
      return;
    case ASSIGN:
      attach_node(ctx, parser, parent, AST_NODE_NONE);
      return;
    default:
      parser_syntax_error(ctx, parser, ": or =");
  }
}

// Changes: new, the shared case labels and the note on clang-format; the unit
// value is the terminal UNIT; TYPE_LIST starts a list creation.
// Case labels of the tokens starting an operand that is no identifier, the
// predict set of the rules starting with NO_IDENT_OPERAND
//
// clang-format takes a macro written as `CASE_FIRST_...:` first in a case
// section for a goto label and misindents the case body after it, so a switch
// with such a section is wrapped in `// clang-format off` and `on` and
// indented by hand like the other switches.
#define CASE_FIRST_NO_IDENT_OPERAND \
  case TYPE_LIST:                   \
  case UNIT:                        \
  case BOOL_TRUE:                   \
  case BOOL_FALSE:                  \
  case NUMBER_INT:                  \
  case NUMBER_DOUBLE:               \
  case STRING:                      \
  case TRIPLE_STRING:               \
  case S_STRING_START:              \
  case TRIPLE_S_STRING_START:       \
  case L_PAREN

// Changes: new, the case labels of FIRST(EXPR), built on
// CASE_FIRST_NO_IDENT_OPERAND.
// Case labels of the tokens starting an expression, FIRST(EXPR): the predict
// set of every rule starting with EXPR
#define CASE_FIRST_EXPR \
  case IDENT:           \
  case OPERATOR_MINUS:  \
  case BOOL_NEG:        \
    CASE_FIRST_NO_IDENT_OPERAND

// Changes: new, forward declaration (STATEMENT_TAIL and STATEMENT_BASE call
// each other).
static void parse_statement_base(Ctx* ctx, Parser* parser, AstNode* block);

// Changes: new, forward declarations of the statements defined further down.
static void parse_statement_if(Ctx* ctx, Parser* parser, AstNode* parent);

static void parse_statement_while(Ctx* ctx, Parser* parser, AstNode* parent);

static void parse_statement_for(Ctx* ctx, Parser* parser, AstNode* parent);

// Changes: new, STATEMENT_TAIL.
// STATEMENT_TAIL -> SEMICOLON STATEMENT_BASE | EOL_TOKEN (rules 109, 110)
// A statement after `;` is the next sibling in the enclosing BLOCK.
static void parse_statement_tail(Ctx* ctx, Parser* parser, AstNode* block) {
  switch (parser_current(parser)->type) {
    case SEMICOLON:
      parser_advance(ctx, parser);
      parse_statement_base(ctx, parser, block);
      return;
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      return;
    default:
      parser_syntax_error(ctx, parser, "; or end of line");
  }
}

// Changes: new, RVALUE; rule 101 sets the EXPR flag on its IF.
// RVALUE -> EXPR STATEMENT_TAIL | STATEMENT_IF (rules 100, 101)
// Attaches the value to the statement given as parent; the statement tail
// belongs to the BLOCK the statement is in, the statement's parent.
static void parse_rvalue(Ctx* ctx, Parser* parser, AstNode* statement) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 100, predict set is FIRST(EXPR)
    CASE_FIRST_EXPR:
      attach_expr(ctx, parser, statement);
      parse_statement_tail(ctx, parser, ast_node_get_parent(statement));
      return;

    // Rule 101: the IF on the right side is an if expression (GLOSSARY.md); it
    // is the statement's last child, the ; form appends to the BLOCK instead
    case IF: {
      size_t index = ast_node_get_child_count(statement);
      parse_statement_if(ctx, parser, statement);
      AstNode* node;
      ast_node_get_child(ctx, statement, index, &node);
      ast_node_set_flags(node,
                         ast_node_get_flags(node) | (unsigned)AST_FLAG_EXPR);
      return;
    }

    default:
      parser_syntax_error(ctx, parser, "expression");
  }
  // clang-format on
}

// Changes: new, VAR_TYPE.
// VAR_TYPE -> COLON TYPE | ε (rules 116, 117)
// Attaches the type annotation, NONE when omitted.
static void parse_var_type(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case COLON:
      parser_advance(ctx, parser);
      parse_type(ctx, parser, parent);
      return;
    case ASSIGN:
      attach_node(ctx, parser, parent, AST_NODE_NONE);
      return;
    default:
      parser_syntax_error(ctx, parser, ": or =");
  }
}

// Changes: new, RETURN_VAL; a token starting no value is reported here.
// RETURN_VAL -> RVALUE | STATEMENT_TAIL (rules 118, 119)
// Attaches the value to the RETURN given as parent, NONE when omitted.
static void parse_return_val(Ctx* ctx, Parser* parser, AstNode* ret) {
  switch (parser_current(parser)->type) {
    case SEMICOLON:
    case EOL_TOKEN:
      attach_node(ctx, parser, ret, AST_NODE_NONE);
      parse_statement_tail(ctx, parser, ast_node_get_parent(ret));
      return;
    // Rule 118, predict set is FIRST(RVALUE)
    case IF:
    CASE_FIRST_EXPR:
      parse_rvalue(ctx, parser, ret);
      return;

    default:
      parser_syntax_error(ctx, parser, "expression, if, ; or end of line");
  }
}

// Changes: new, peeks for `=` to tell an assignment from an expression.
// STATEMENT_ID -> ASSIGN RVALUE | EXPR_TAIL STATEMENT_TAIL (rules 120, 121)
// Entered with the IDENT still current.
static void parse_statement_id(Ctx* ctx, Parser* parser, AstNode* block) {
  if (parser_peek(ctx, parser)->type != ASSIGN) {
    attach_expr(ctx, parser, block);
    parse_statement_tail(ctx, parser, block);
    return;
  }

  // Rule 120: ASSIGN [ident, expr]
  AstNode* assign = attach_node(ctx, parser, block, AST_NODE_ASSIGN);
  attach_ident(ctx, parser, assign);
  parser_expect(ctx, parser, ASSIGN);
  parse_rvalue(ctx, parser, assign);
}

// Changes: new, an expression statement is the expression node itself.
// STATEMENT_BASE -> VAL IDENT VAR_TYPE ASSIGN RVALUE
//                 | VAR IDENT VAR_TYPE ASSIGN RVALUE | RETURN RETURN_VAL
//                 | IDENT STATEMENT_ID
//                 | NO_IDENT_OPERAND EXPR_TAIL STATEMENT_TAIL (rules 111 to
// 115)
static void parse_statement_base(Ctx* ctx, Parser* parser, AstNode* block) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rules 111 and 112: VAL and VAR [ident, type|NONE, init]
    case VAL:
    case VAR: {
      AstNode* declaration = attach_node(
          ctx, parser, block,
          parser_current(parser)->type == VAL ? AST_NODE_VAL : AST_NODE_VAR);
      parser_advance(ctx, parser);
      attach_ident(ctx, parser, declaration);
      parse_var_type(ctx, parser, declaration);
      parser_expect(ctx, parser, ASSIGN);
      parse_rvalue(ctx, parser, declaration);
      return;
    }

    // Rule 113: RETURN [expr|NONE]
    case RETURN: {
      AstNode* ret = attach_node(ctx, parser, block, AST_NODE_RETURN);
      parser_advance(ctx, parser);
      parse_return_val(ctx, parser, ret);
      return;
    }

    case IDENT:
      parse_statement_id(ctx, parser, block);
      return;

    // NO_IDENT_OPERAND: a literal or ( , handed to the precedence parser
    CASE_FIRST_NO_IDENT_OPERAND:
      attach_expr(ctx, parser, block);
      parse_statement_tail(ctx, parser, block);
      return;

    default:
      parser_syntax_error(ctx, parser, "statement");
  }
  // clang-format on
}

// Changes: new, STATEMENT.
// STATEMENT -> STATEMENT_BASE | STATEMENT_IF | STATEMENT_WHILE | STATEMENT_FOR
// (rules 105 to 108)
static void parse_statement(Ctx* ctx, Parser* parser, AstNode* block) {
  switch (parser_current(parser)->type) {
    case IDENT:
    case VAL:
    case VAR:
    case RETURN:
    CASE_FIRST_NO_IDENT_OPERAND:
      parse_statement_base(ctx, parser, block);
      return;

    case IF:
      parse_statement_if(ctx, parser, block);
      return;

    case WHILE:
      parse_statement_while(ctx, parser, block);
      return;

    case FOR:
      parse_statement_for(ctx, parser, block);
      return;

    default:
      parser_syntax_error(ctx, parser, "statement");
  }
}

// Changes: new, tells a block close from a block open (both INDENT in the LL
// table).
/**
 * @brief Whether the current token is a block close (GLOSSARY.md, Block open /
 * Block close).
 *
 * A block open is the raw indent itself (value.integer is its indentation,
 * deeper than the enclosing block's, so above 0); a block close is made by the
 * token layer with value.integer 0.
 */
static bool at_block_close(const Parser* parser) {
  return parser_current(parser)->type == INDENT &&
         parser_current(parser)->value.integer == 0;
}

// Changes: new, consumes a block close; a block open there is a syntax error.
/**
 * @brief Consumes the current token if it is a block close, otherwise throws a
 * syntax error.
 */
static void expect_block_close(Ctx* ctx, Parser* parser) {
  if (!at_block_close(parser))
    parser_syntax_error(ctx, parser, "end of the indented block");
  parser_advance(ctx, parser);
}

// Changes: new, STATEMENT_LIST as a loop up to the block close.
// STATEMENT_LIST -> STATEMENT STATEMENT_LIST | ε (rules 103, 104)
// The predict set of the ε rule is FOLLOW(STATEMENT_LIST) = { INDENT }, which
// here can only be the block close.
static void parse_statement_list(Ctx* ctx, Parser* parser, AstNode* block) {
  // The right recursion is a loop, so long blocks do not nest calls
  while (!at_block_close(parser))
    parse_statement(ctx, parser, block);
}

// Changes: new, BLOCK.
// BLOCK -> INDENT STATEMENT STATEMENT_LIST INDENT (rule 102)
// Attaches a BLOCK [stmt...] to parent; the first INDENT is the block open, the
// last one the block close.
static void parse_block(Ctx* ctx, Parser* parser, AstNode* parent) {
  if (parser_current(parser)->type != INDENT || at_block_close(parser))
    parser_syntax_error(ctx, parser, "indented block");

  AstNode* block = attach_node(ctx, parser, parent, AST_NODE_BLOCK);
  parser_advance(ctx, parser);
  parse_statement(ctx, parser, block);
  parse_statement_list(ctx, parser, block);
  expect_block_close(ctx, parser);
}

// Changes: new, the case labels of FIRST(INLINE_BODY).
// Case labels of the tokens starting a single-line body, FIRST(INLINE_BODY):
// `return` and the tokens starting an expression
#define CASE_FIRST_INLINE_BODY \
  case RETURN:                 \
    CASE_FIRST_EXPR

// Changes: new, where the statement after `;` of an if goes.
/**
 * @brief Returns the BLOCK a node is in: the node itself when it is a BLOCK,
 * otherwise its nearest ancestor that is.
 *
 * Every if statement is below a BLOCK, as every statement is.
 */
static AstNode* enclosing_block(AstNode* node) {
  while (ast_node_get_type(node) != AST_NODE_BLOCK)
    node = ast_node_get_parent(node);
  return node;
}

// Changes: new, INLINE_RETURN_VAL.
// INLINE_RETURN_VAL -> EXPR | ε (rules 127, 128)
// Attaches the value to the RETURN given as parent, NONE when omitted.
static void parse_inline_return_val(Ctx* ctx, Parser* parser, AstNode* ret) {
  // clang-format off
  switch (parser_current(parser)->type) {
    CASE_FIRST_EXPR:
      attach_expr(ctx, parser, ret);
      return;

    // The predict set of the ε rule is FOLLOW(INLINE_RETURN_VAL)
    case ELSE:
    case SEMICOLON:
    case EOL_TOKEN:
      attach_node(ctx, parser, ret, AST_NODE_NONE);
      return;

    default:
      parser_syntax_error(ctx, parser, "expression, else, ; or end of line");
  }
  // clang-format on
}

// Changes: new, peeks for `=`, like STATEMENT_ID.
// INLINE_ID -> ASSIGN EXPR | EXPR_TAIL (rules 129, 130)
// Entered with the IDENT still current.
static void parse_inline_id(Ctx* ctx, Parser* parser, AstNode* block) {
  if (parser_peek(ctx, parser)->type != ASSIGN) {
    attach_expr(ctx, parser, block);
    return;
  }

  // Rule 129: ASSIGN [ident, expr]
  AstNode* assign = attach_node(ctx, parser, block, AST_NODE_ASSIGN);
  attach_ident(ctx, parser, assign);
  parser_expect(ctx, parser, ASSIGN);
  attach_expr(ctx, parser, assign);
}

// Changes: new, an expression is the expression node itself; ends before the
// `else`, `;` or end of line that follows.
// INLINE_BODY -> RETURN INLINE_RETURN_VAL | IDENT INLINE_ID
//              | NO_IDENT_OPERAND EXPR_TAIL
//              | OPERATOR_MINUS UNARY BINARY_TAIL
//              | BOOL_NEG UNARY BINARY_TAIL (rules 122 to 126)
static void parse_inline_body(Ctx* ctx, Parser* parser, AstNode* block) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 122: RETURN [expr|NONE]
    case RETURN: {
      AstNode* ret = attach_node(ctx, parser, block, AST_NODE_RETURN);
      parser_advance(ctx, parser);
      parse_inline_return_val(ctx, parser, ret);
      return;
    }

    case IDENT:
      parse_inline_id(ctx, parser, block);
      return;

    // NO_IDENT_OPERAND, `-` and `!`: an expression for the precedence parser
    CASE_FIRST_NO_IDENT_OPERAND:
    case OPERATOR_MINUS:
    case BOOL_NEG:
      attach_expr(ctx, parser, block);
      return;

    default:
      parser_syntax_error(ctx, parser, "single-line statement");
  }
  // clang-format on
}

// Changes: new, ELSE_BODY.
// ELSE_BODY -> STATEMENT_IF | EOL_TOKEN BLOCK | INLINE_BODY STATEMENT_TAIL
// (rules 139 to 141). Attaches the else child to the IF given as parent: the
// IF of an `else if`, or a BLOCK.
static void parse_else_body(Ctx* ctx, Parser* parser, AstNode* if_node) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 139: `else if` is an IF as the else child
    case IF:
      parse_statement_if(ctx, parser, if_node);
      return;

    // Rule 140: the else branch is the indented block on the following lines
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      parse_block(ctx, parser, if_node);
      return;

    // Rule 141: a single-line body is wrapped in a BLOCK; a statement after
    // `;` is the next sibling in the BLOCK the whole if is in
    CASE_FIRST_INLINE_BODY: {
      AstNode* block = attach_node(ctx, parser, if_node, AST_NODE_BLOCK);
      parse_inline_body(ctx, parser, block);
      parse_statement_tail(ctx, parser, enclosing_block(if_node));
      return;
    }

    default:
      parser_syntax_error(ctx, parser, "if, statement or end of line");
  }
  // clang-format on
}

// Changes: new, ELSE_PART; a block open after a statement is reported at once.
// ELSE_PART -> ELSE ELSE_BODY | ε (rules 134, 135)
// Attaches the else child to the IF given as parent, NONE when there is no
// `else`: a missing else is never a syntax error by itself.
static void parse_else_part(Ctx* ctx, Parser* parser, AstNode* if_node) {
  switch (parser_current(parser)->type) {
    case ELSE:
      parser_advance(ctx, parser);
      parse_else_body(ctx, parser, if_node);
      return;

    // Rule 135, predict set is FOLLOW(ELSE_PART), the tokens that continue
    // after a statement
    case IDENT:
    case AT_MAIN:
    case DEF:
    case VAL:
    case VAR:
    case RETURN:
    case IF:
    case WHILE:
    case FOR:
    CASE_FIRST_NO_IDENT_OPERAND:
    case INDENT:
    case EOF_TOKEN:
      if (parser_current(parser)->type == INDENT && !at_block_close(parser))
        parser_syntax_error(ctx, parser, "else or the next statement");
      attach_node(ctx, parser, if_node, AST_NODE_NONE);
      return;

    default:
      parser_syntax_error(ctx, parser, "else or the next statement");
  }
}

// Changes: new, INLINE_ELSE_PART.
// INLINE_ELSE_PART -> ELSE ELSE_BODY | SEMICOLON STATEMENT_BASE
//                   | EOL_TOKEN ELSE_PART (rules 136 to 138)
// Attaches the else child to the IF given as parent.
static void parse_inline_else_part(Ctx* ctx, Parser* parser, AstNode* if_node) {
  switch (parser_current(parser)->type) {
    case ELSE:
      parser_advance(ctx, parser);
      parse_else_body(ctx, parser, if_node);
      return;

    // Rule 137: the IF has no else; the statement after `;` is the next
    // sibling of the IF in its BLOCK, never part of the then branch
    case SEMICOLON:
      attach_node(ctx, parser, if_node, AST_NODE_NONE);
      parser_advance(ctx, parser);
      parse_statement_base(ctx, parser, enclosing_block(if_node));
      return;

    // Rule 138: an `else` may follow on the next line
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      parse_else_part(ctx, parser, if_node);
      return;

    default:
      parser_syntax_error(ctx, parser, "else, ; or end of line");
  }
}

// Changes: new, IF_BODY.
// IF_BODY -> EOL_TOKEN BLOCK ELSE_PART | INLINE_BODY INLINE_ELSE_PART
// (rules 132, 133). Attaches the then BLOCK and the else child to the IF given
// as parent.
static void parse_if_body(Ctx* ctx, Parser* parser, AstNode* if_node) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 132: the then branch is the indented block on the following lines
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      parse_block(ctx, parser, if_node);
      parse_else_part(ctx, parser, if_node);
      return;

    // Rule 133: a single-line body is wrapped in a BLOCK
    CASE_FIRST_INLINE_BODY: {
      AstNode* block = attach_node(ctx, parser, if_node, AST_NODE_BLOCK);
      parse_inline_body(ctx, parser, block);
      parse_inline_else_part(ctx, parser, if_node);
      return;
    }

    default:
      parser_syntax_error(ctx, parser, "statement or end of line");
  }
  // clang-format on
}

// Changes: new; the EXPR flag is set by the right side that takes the IF.
// STATEMENT_IF -> IF EXPR THEN IF_BODY (rule 131)
// Attaches an IF [cond, then BLOCK, else BLOCK|IF|NONE] to parent.
static void parse_statement_if(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IF: {
      AstNode* if_node = attach_node(ctx, parser, parent, AST_NODE_IF);
      parser_advance(ctx, parser);
      attach_expr(ctx, parser, if_node);
      parser_expect(ctx, parser, THEN);
      parse_if_body(ctx, parser, if_node);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "if");
  }
}

// Changes: new, LOOP_BODY.
// LOOP_BODY -> EOL_TOKEN BLOCK | INLINE_BODY STATEMENT_TAIL (rules 155, 156)
// Attaches the body BLOCK to the loop given as parent.
static void parse_loop_body(Ctx* ctx, Parser* parser, AstNode* loop) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 155: the body is the indented block on the following lines
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      parse_block(ctx, parser, loop);
      return;

    // Rule 156: a single-line body is wrapped in a BLOCK; a statement after
    // `;` is the next sibling in the BLOCK the whole loop is in
    CASE_FIRST_INLINE_BODY: {
      AstNode* block = attach_node(ctx, parser, loop, AST_NODE_BLOCK);
      parse_inline_body(ctx, parser, block);
      parse_statement_tail(ctx, parser, enclosing_block(loop));
      return;
    }

    default:
      parser_syntax_error(ctx, parser, "statement or end of line");
  }
  // clang-format on
}

// Changes: new, STATEMENT_WHILE.
// STATEMENT_WHILE -> WHILE EXPR DO LOOP_BODY (rule 142)
// Attaches a WHILE [cond, BLOCK] to parent.
static void parse_statement_while(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case WHILE: {
      AstNode* loop = attach_node(ctx, parser, parent, AST_NODE_WHILE);
      parser_advance(ctx, parser);
      attach_expr(ctx, parser, loop);
      parser_expect(ctx, parser, DO);
      parse_loop_body(ctx, parser, loop);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "while");
  }
}

// Changes: new, the text check of `to`, `until` and `by`.
/**
 * @brief Whether the current token is the identifier spelling the given
 * contextual keyword (GLOSSARY.md, Contextual keyword).
 *
 * The text is only compared, the token is not consumed.
 */
static bool at_contextual_keyword(const Parser* parser, const char* keyword) {
  return parser_current(parser)->type == IDENT &&
         strcmp(parser_current(parser)->value.text, keyword) == 0;
}

// Changes: new, RANGE_STEP.
// RANGE_STEP -> IDENT EXPR | ε (rules 149, 150)
// Attaches the step to the RANGE_TO or RANGE_UNTIL given as parent, NONE when
// there is no `by`.
static void parse_range_step(Ctx* ctx, Parser* parser, AstNode* range) {
  switch (parser_current(parser)->type) {
    // Rule 149: the IDENT is the contextual keyword `by`, any other word is a
    // syntax error
    case IDENT:
      if (!at_contextual_keyword(parser, "by"))
        parser_syntax_error(ctx, parser, "by, if, do or end of line");
      parser_advance(ctx, parser);
      attach_expr(ctx, parser, range);
      return;

    // Rule 150, predict set is FOLLOW(RANGE_STEP)
    case DO:
    case IF:
    case EOL_TOKEN:
    case R_PAREN:
      attach_node(ctx, parser, range, AST_NODE_NONE);
      return;

    default:
      parser_syntax_error(ctx, parser, "by, if, do or end of line");
  }
}

// Changes: RANGE_TAIL -> ε leaves the source, a list expression, as it is.
// GENERATOR -> IDENT CONTROL_ARROW EXPR RANGE_TAIL (rule 146)
// RANGE_TAIL -> IDENT EXPR RANGE_STEP | ε (rules 147, 148)
// Attaches the loop variable and the source to the FOR given as parent: a
// RANGE_TO or RANGE_UNTIL [from, to, step|NONE] or the list expression.
static void parse_generator(Ctx* ctx, Parser* parser, AstNode* for_node) {
  switch (parser_current(parser)->type) {
    case IDENT: {
      attach_ident(ctx, parser, for_node);
      parser_expect(ctx, parser, CONTROL_ARROW);

      // The range node is attached before the first expression is parsed
      // (which ends at the contextual keyword), so a syntax error frees the
      // value with it; its kind is known only after the keyword is read
      AstNode* range = attach_node(ctx, parser, for_node, AST_NODE_RANGE_TO);
      attach_expr(ctx, parser, range);

      switch (parser_current(parser)->type) {
        // The IDENT is `to` or `until`, any other word is a syntax error
        case IDENT:
          if (at_contextual_keyword(parser, "until"))
            ast_node_set_type(range, AST_NODE_RANGE_UNTIL);
          else if (!at_contextual_keyword(parser, "to"))
            parser_syntax_error(ctx, parser,
                                "to, until, if, do or end of line");
          parser_advance(ctx, parser);

          attach_expr(ctx, parser, range);
          parse_range_step(ctx, parser, range);
          return;

        // Rule 148, predict set is FOLLOW(RANGE_TAIL): the expression is a
        // list source and takes the place of the range node. Detaching frees
        // a slot of the FOR, so the append cannot fail
        case DO:
        case IF:
        case EOL_TOKEN:
        case R_PAREN: {
          AstNode* source;
          ast_node_detach_child(ctx, range, 0, &source);
          ast_node_detach_child(ctx, for_node,
                                ast_node_get_child_count(for_node) - 1, &range);
          ast_node_destroy(ctx, range);
          parser_attach(ctx, parser, for_node, source);
          return;
        }

        default:
          parser_syntax_error(ctx, parser, "to, until, if, do or end of line");
      }
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "identifier");
  }
}

// Changes: new, GUARD_LIST.
// GUARD_LIST -> IF EXPR GUARD_LIST | ε (rules 151, 152)
// Attaches every guard condition to the FOR given as parent.
static void parse_guard_list(Ctx* ctx, Parser* parser, AstNode* for_node) {
  // The right recursion is a loop, so long guard lists do not nest calls
  while (true) {
    switch (parser_current(parser)->type) {
      case IF:
        parser_advance(ctx, parser);
        attach_expr(ctx, parser, for_node);
        continue;

      // Rule 152, predict set is FOLLOW(GUARD_LIST)
      case DO:
        return;

      default:
        parser_syntax_error(ctx, parser, "if or do");
    }
  }
}

// Changes: new, GUARD_LINES.
// GUARD_LINES -> IF EXPR EOL_TOKEN GUARD_LINES | ε (rules 153, 154)
// Attaches every guard condition to the FOR given as parent.
static void parse_guard_lines(Ctx* ctx, Parser* parser, AstNode* for_node) {
  // The right recursion is a loop, so long guard lists do not nest calls
  while (true) {
    switch (parser_current(parser)->type) {
      case IF:
        parser_advance(ctx, parser);
        attach_expr(ctx, parser, for_node);
        parser_expect(ctx, parser, EOL_TOKEN);
        continue;

      // Rule 154, predict set is FOLLOW(GUARD_LINES), the block close that
      // ends the header; a block open here is a syntax error
      case INDENT:
        if (!at_block_close(parser))
          parser_syntax_error(ctx, parser, "if or the end of the header");
        return;

      default:
        parser_syntax_error(ctx, parser, "if or the end of the header");
    }
  }
}

// Changes: new, FOR_HEADER.
// FOR_HEADER -> GENERATOR GUARD_LIST
//             | EOL_TOKEN INDENT GENERATOR EOL_TOKEN GUARD_LINES INDENT
// (rules 144, 145)
// In the multi-line form the first INDENT opens and the last closes a block.
static void parse_for_header(Ctx* ctx, Parser* parser, AstNode* for_node) {
  switch (parser_current(parser)->type) {
    case IDENT:
      parse_generator(ctx, parser, for_node);
      parse_guard_list(ctx, parser, for_node);
      return;

    case EOL_TOKEN:
      parser_advance(ctx, parser);
      if (parser_current(parser)->type != INDENT || at_block_close(parser))
        parser_syntax_error(ctx, parser, "indented generator");
      parser_advance(ctx, parser);
      parse_generator(ctx, parser, for_node);
      parser_expect(ctx, parser, EOL_TOKEN);
      parse_guard_lines(ctx, parser, for_node);
      expect_block_close(ctx, parser);
      return;

    default:
      parser_syntax_error(ctx, parser, "identifier or end of line");
  }
}

// Changes: new; the body BLOCK is moved to AST_FOR_BODY, before the guards.
// STATEMENT_FOR -> FOR FOR_HEADER DO LOOP_BODY (rule 143)
// Attaches a FOR [ident, source, BLOCK, guard...] to parent.
static void parse_statement_for(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case FOR: {
      AstNode* for_node = attach_node(ctx, parser, parent, AST_NODE_FOR);
      parser_advance(ctx, parser);
      parse_for_header(ctx, parser, for_node);
      parser_expect(ctx, parser, DO);
      parse_loop_body(ctx, parser, for_node);

      // Detaching frees a slot, so inserting cannot fail
      AstNode* body;
      ast_node_detach_child(ctx, for_node,
                            ast_node_get_child_count(for_node) - 1, &body);
      ast_node_insert_child(ctx, for_node, AST_FOR_BODY, body);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "for");
  }
}

// Changes: rules 28 and 29: an if statement or a multi-line body, both as the
// body's BLOCK.
// FUNC_BODY -> EXPR EOL_TOKEN | STATEMENT_IF | EOL_TOKEN BLOCK
// (rules 27 to 29). Attaches the body as a BLOCK.
static void parse_func_body(Ctx* ctx, Parser* parser, AstNode* parent) {
  // clang-format off
  switch (parser_current(parser)->type) {
    // Rule 27, predict set is FIRST(EXPR); a single-line body is wrapped in a
    // BLOCK
    CASE_FIRST_EXPR: {
      AstNode* block = attach_node(ctx, parser, parent, AST_NODE_BLOCK);
      attach_expr(ctx, parser, block);
      parser_expect(ctx, parser, EOL_TOKEN);
      return;
    }

    // Rule 29: the body is the indented block on the following lines
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      parse_block(ctx, parser, parent);
      return;

    // Rule 28: a body that is an if statement is wrapped in a BLOCK as well
    case IF: {
      AstNode* block = attach_node(ctx, parser, parent, AST_NODE_BLOCK);
      parse_statement_if(ctx, parser, block);
      return;
    }

    default:
      parser_syntax_error(ctx, parser, "expression, if or end of line");
  }
  // clang-format on
}

// Changes: new, INLINE_VALUE; rule 98 goes through parse_if_inline.
// INLINE_VALUE -> EXPR | IF_INLINE (rules 97, 98), a full value in an argument
// or in `${...}`.
void parse_inline_value(Ctx* ctx, Parser* parser, AstNode* parent) {
  // clang-format off
  switch (parser_current(parser)->type) {
    CASE_FIRST_EXPR:
      attach_expr(ctx, parser, parent);
      return;
    case IF:
      parse_if_inline(ctx, parser, parent);
      return;
    default:
      parser_syntax_error(ctx, parser, "expression");
  }
  // clang-format on
}

// Changes: new, the callback for `(if ...)`; an `else if` is an IF as the else
// child.
// IF_INLINE -> IF EXPR THEN INLINE_VALUE ELSE INLINE_VALUE (rule 99)
// Attaches an IF [cond, then BLOCK, else BLOCK|IF] with the EXPR flag to
// parent; a value after `then` or `else` is wrapped in a BLOCK.
void parse_if_inline(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IF: {
      AstNode* if_node = attach_node(ctx, parser, parent, AST_NODE_IF);
      ast_node_set_flags(if_node, (unsigned)AST_FLAG_EXPR);
      parser_advance(ctx, parser);
      attach_expr(ctx, parser, if_node);
      parser_expect(ctx, parser, THEN);

      AstNode* then_block = attach_node(ctx, parser, if_node, AST_NODE_BLOCK);
      parse_inline_value(ctx, parser, then_block);
      parser_expect(ctx, parser, ELSE);

      if (parser_current(parser)->type == IF) {
        parse_inline_value(ctx, parser, if_node);
        return;
      }
      AstNode* else_block = attach_node(ctx, parser, if_node, AST_NODE_BLOCK);
      parse_inline_value(ctx, parser, else_block);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "if");
  }
}

// Changes: new, forward declaration (ARG_NEXT and ARG_TAIL call each other).
static void parse_arg_tail(Ctx* ctx, Parser* parser, AstNode* parent);

// Changes: new, ARG_NEXT.
// ARG_NEXT -> INLINE_VALUE ARG_TAIL | ε (rules 95, 96)
static void parse_arg_next(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IF:
    CASE_FIRST_EXPR:
      parse_inline_value(ctx, parser, parent);
      parse_arg_tail(ctx, parser, parent);
      return;
    // The comma was a trailing one
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, "expression or )");
  }
}

// Changes: new, ARG_TAIL; the COMMA goes through parse_list_comma.
// ARG_TAIL -> COMMA ARG_NEXT | ε (rules 93, 94)
static void parse_arg_tail(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case COMMA:
      parse_list_comma(ctx, parser);
      parse_arg_next(ctx, parser, parent);
      return;
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, ", or )");
  }
}

// Changes: new, ARG_LIST, the callback for call arguments.
// ARG_LIST -> INLINE_VALUE ARG_TAIL | ε (rules 91, 92)
void parse_arg_list(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IF:
    CASE_FIRST_EXPR:
      parse_inline_value(ctx, parser, parent);
      parse_arg_tail(ctx, parser, parent);
      return;
    case R_PAREN:
      return;
    default:
      parser_syntax_error(ctx, parser, "expression or )");
  }
}

// MAIN_TAIL -> EOL_TOKEN | ε (rules 7, 8)
static void parse_main_tail(Ctx* ctx, Parser* parser) {
  switch (parser_current(parser)->type) {
    case EOL_TOKEN:
      parser_advance(ctx, parser);
      return;
    case DEF:
      return;
    default:
      parser_syntax_error(ctx, parser, "def or end of line");
  }
}

// MAIN -> AT_MAIN MAIN_TAIL | ε (rules 5, 6)
// Sets the MAIN flag of the DEF given as parent.
static void parse_main(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case AT_MAIN:
      ast_node_set_flags(parent,
                         ast_node_get_flags(parent) | (unsigned)AST_FLAG_MAIN);
      parser_advance(ctx, parser);
      parse_main_tail(ctx, parser);
      return;
    case DEF:
      return;
    default:
      parser_syntax_error(ctx, parser, "@main or def");
  }
}

// Changes: the PARAM_LIST directly follows the ident.
// FUNC -> MAIN DEF IDENT FUNC_PARAMS FUNC_TYPE ASSIGN FUNC_BODY (rule 15)
// Attaches a DEF [ident, rettype|NONE, BLOCK, PARAM_LIST].
static void parse_func(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case AT_MAIN:
    case DEF: {
      AstNode* def = attach_node(ctx, parser, parent, AST_NODE_DEF);
      parse_main(ctx, parser, def);
      parser_expect(ctx, parser, DEF);
      attach_ident(ctx, parser, def);
      parse_func_params(ctx, parser, def);
      parse_func_type(ctx, parser, def);
      parser_expect(ctx, parser, ASSIGN);
      parse_func_body(ctx, parser, def);

      // The source order is [ident, PARAM_LIST, rettype, BLOCK]; move the
      // PARAM_LIST last. Detaching frees a slot, so appending cannot fail.
      AstNode* params;
      ast_node_detach_child(ctx, def, AST_DEF_IDENT + 1, &params);
      ast_node_append_child(ctx, def, params);
      return;
    }
    default:
      parser_syntax_error(ctx, parser, "@main or def");
  }
}

// FUNC_LIST -> FUNC FUNC_LIST | ε (rules 3, 4)
static void parse_func_list(Ctx* ctx, Parser* parser, AstNode* parent) {
  // The right recursion is a loop, so long programs do not nest calls
  while (true) {
    switch (parser_current(parser)->type) {
      case AT_MAIN:
      case DEF:
        parse_func(ctx, parser, parent);
        continue;
      case EOF_TOKEN:
        return;
      default:
        parser_syntax_error(ctx, parser, "@main, def or end of file");
    }
  }
}

// PROLOG -> IMPORT IDENT PERIOD OPERATOR_MULTIPLY EOL_TOKEN (rule 2)
// Produces no node.
static void parse_prolog(Ctx* ctx, Parser* parser) {
  parser_expect(ctx, parser, IMPORT);

  // `ifj26` is a contextual keyword (GLOSSARY.md, Contextual keyword)
  if (parser_current(parser)->type != IDENT ||
      strcmp(parser_current(parser)->value.text, "ifj26") != 0)
    parser_syntax_error(ctx, parser, "ifj26");
  parser_advance(ctx, parser);

  parser_expect(ctx, parser, PERIOD);
  parser_expect(ctx, parser, OPERATOR_MULTIPLY);
  parser_expect(ctx, parser, EOL_TOKEN);
}

// PROGRAM -> PROLOG FUNC_LIST EOF_TOKEN (rule 1), the start nonterminal
// Attaches the functions to the PROGRAM root given as parent.
static void parse_program(Ctx* ctx, Parser* parser, AstNode* parent) {
  switch (parser_current(parser)->type) {
    case IMPORT:
      parse_prolog(ctx, parser);
      parse_func_list(ctx, parser, parent);
      parser_expect(ctx, parser, EOF_TOKEN);
      return;
    default:
      parser_syntax_error(ctx, parser, "import");
  }
}

// === ENTRY POINT ===

void parser_run(Ctx* ctx, TokenSourceNext next, void* source) {
  parser_init(ctx, next, source);

  // The root is stored in ctx before parsing, so a partly built tree is freed
  // by ctx_free when an error is thrown
  AstNode* root;
  ast_node_create(ctx, &root);
  ast_node_set_type(root, AST_NODE_PROGRAM);
  ast_node_set_position(root, parser_current(ctx->parser)->line,
                        parser_current(ctx->parser)->column);
  ctx->ast = root;

  parse_program(ctx, ctx->parser, root);

  parser_cleanup(ctx);
}

// Changes: the lexer is the token layer's token source.
void parser_parse(Ctx* ctx) {
  parser_run(ctx, token_layer_lexer_next, NULL);
}
